#!/usr/bin/env bash
# Generated by Claude (Anthropic's AI assistant, via Claude Code), October 2026. See Tools/Publish/README.md.
# Checks that the public part of the project (Assets/Lab) can be published.
# Run from the repo root: Tools/Publish/check-public.sh
# Exit code 1 if any blocking issue is found; warnings don't fail the check.
set -uo pipefail
KEEP_TMP=${KEEP_TMP:-}
cd "$(git rev-parse --show-toplevel)"

PUBLIC="Assets/Lab"
fail=0
tmp=$(mktemp -d); [ -n "$KEEP_TMP" ] || trap 'rm -rf "$tmp"' EXIT

section() { printf '\n== %s\n' "$1"; }

# --- 1. Asset references from public to private/licensed content -----------------
# Map every GUID to its path. Samples exist both in Assets/Samples and in the package cache;
# the first (Assets) path wins so sample dependencies are recognised.
find Assets Packages Library/PackageCache -name '*.meta' -print0 2>/dev/null \
    | xargs -0 grep -m1 -H '^guid:' \
    | sed -E 's/\.meta:guid: */\t/' | awk -F'\t' '!($2 in seen){seen[$2]=1; print $2"\t"$1}' > "$tmp/guids.tsv"

# GUIDs referenced by public YAML assets, resolved to paths
find "$PUBLIC" -type f \( -name '*.unity' -o -name '*.prefab' -o -name '*.mat' -o -name '*.asset' \
    -o -name '*.controller' -o -name '*.anim' -o -name '*.asmdef' -o -name '*.lighting' \
    -o -name '*.overrideController' -o -name '*.shadergraph' -o -name '*.playable' \) -print0 \
    | xargs -0 grep -HoE 'guid: [0-9a-f]{32}|GUID:[0-9a-f]{32}' \
    | sed -E 's/:(guid: |GUID:)/\t/' | sort -u \
    | awk -F'\t' 'NR==FNR{p[$1]=$2; next} ($2 in p){print $1"\t"p[$2]}' "$tmp/guids.tsv" - > "$tmp/resolved.tsv"

list() { grep -E $'\t'"$1" "$tmp/resolved.tsv" | sort -u \
    | awk -F'\t' '{if($1!=last){print $1; last=$1} sub(/^Assets\//,"",$2); print "    -> "$2}'; }

section "Public assets referencing private or licensed content (blocking)"
list 'Assets/(LabPrivate|ThirdParty|Oculus/SampleFramework)/' > "$tmp/forbidden.txt"
if [ -s "$tmp/forbidden.txt" ]; then cat "$tmp/forbidden.txt"; fail=1; else echo "none"; fi

section "Public assets that need a Package Manager sample (not shipped; users must import it)"
list 'Assets/Samples/' || echo "none"

section "Public assets referencing other project folders (must move into $PUBLIC for UPM)"
grep -E $'\t''Assets/' "$tmp/resolved.tsv" | grep -vE $'\t'"($PUBLIC/|Assets/(LabPrivate|ThirdParty|Oculus/SampleFramework|Samples)/)" \
    | awk -F'\t' '{split($2,a,"/"); print a[1]"/"a[2]"/"a[3]}' | sort | uniq -c || true

# --- 2. Infrastructure hosts and secrets in public files ---------------------------
section "Hard-coded hosts / IPs in public code and assets (should come from config)"
grep -rnoE '[a-z0-9.-]+\.texttechnologylab\.org|https?://([0-9]{1,3}\.){3}[0-9]{1,3}' \
    --include=*.cs --include=*.prefab --include=*.unity --include=*.asset "$PUBLIC" \
    | grep -vE 'www.texttechnologylab.org|//127.0.0.1' | awk -F: '{print $1": "$NF}' | sort -u || true

section "Possible secrets in public files (blocking)"
if grep -rnIE '(sk-[A-Za-z0-9_-]{20,}|AKIA[0-9A-Z]{16}|-----BEGIN [A-Z ]*PRIVATE KEY-----|(api[_-]?key|pass(word)?|secret|token|credential)\w*[" ]*[:=] *"[^"]{4,}")' \
    -i --include=*.cs --include=*.asset --include=*.json --include=*.prefab --include=*.unity --include=*.txt "$PUBLIC" ProjectSettings; then
    fail=1
else echo "none"; fi

# --- 3. Project settings -------------------------------------------------------------
section "Signing configuration (blocking if it points at a keystore)"
if grep -nE "AndroidKeystoreName: .+[^' ]" ProjectSettings/ProjectSettings.asset | grep -v "AndroidKeystoreName: ''"; then
    echo "-> clear AndroidKeystoreName before publishing (keystore stays in LabPrivate)"; fail=1
else echo "ok"; fi
if git ls-files "$PUBLIC" ProjectSettings | grep -iE '\.(keystore|jks)$'; then fail=1; fi

printf '\n%s\n' "$([ $fail -eq 0 ] && echo 'PASS' || echo 'FAIL: fix the blocking issues above')"
exit $fail
